/**
 * @summary Full-text vehicle search with server-side filtering
 */
export const getSearchVehiclesUrl = (params?: SearchVehiclesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/vehicles/search?${stringifiedParams}`
    : `/api/vehicles/search`;
};

export const searchVehicles = async (
  params?: SearchVehiclesParams,
  options?: RequestInit,
): Promise<VehicleSearchPage> => {
  return customFetch<VehicleSearchPage>(getSearchVehiclesUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getSearchVehiclesQueryKey = (params?: SearchVehiclesParams) => {
  return [`/api/vehicles/search`, ...(params ? [params] : [])] as const;
};

export const getSearchVehiclesQueryOptions = <
  TData = Awaited<ReturnType<typeof searchVehicles>>,
  TError = ErrorType<unknown>,
>(
  params?: SearchVehiclesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof searchVehicles>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getSearchVehiclesQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof searchVehicles>>> = ({
    signal,
  }) => searchVehicles(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof searchVehicles>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

